begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,aud,role,created_at) values('a9500000-0000-4000-8000-000000000001','push-claim@example.invalid','authenticated','authenticated',now());
insert into public.mobile_push_tokens(id,user_id,expo_push_token,platform,is_active) values('a9500000-0000-4000-8000-000000000002','a9500000-0000-4000-8000-000000000001','ExponentPushToken[claim-test]','ios',true);
insert into public.mobile_notifications(id,user_id,type,category,title,body) values('a9500000-0000-4000-8000-000000000003','a9500000-0000-4000-8000-000000000001','post_saved','social','Fixture','Local only');
insert into public.mobile_push_deliveries(id,notification_id,user_id,token_id,expo_push_token,platform,send_status,receipt_status,attempt_count) values('a9500000-0000-4000-8000-000000000004','a9500000-0000-4000-8000-000000000003','a9500000-0000-4000-8000-000000000001','a9500000-0000-4000-8000-000000000002','ExponentPushToken[claim-test]','ios','error','error',1);
select ok(not p.prosecdef and p.proconfig @> array['search_path=""'], 'claim uses invoker rights and fixed path') from pg_proc p where p.oid='public.claim_mobile_push_retry(uuid,integer)'::regprocedure;
select ok(not has_function_privilege('anon','public.claim_mobile_push_retry(uuid,integer)','execute'),'anonymous cannot claim');
select ok(not has_function_privilege('authenticated','public.claim_mobile_push_retry(uuid,integer)','execute'),'authenticated cannot claim');
select ok(not has_function_privilege('anon','public.finish_mobile_push_retry(uuid,uuid)','execute'),'anonymous cannot finalize');
select ok(not has_function_privilege('authenticated','public.finish_mobile_push_retry(uuid,uuid)','execute'),'authenticated cannot finalize');
select ok(not has_function_privilege('authenticated','public.record_mobile_push_retry_outcome(uuid,uuid,jsonb)','execute'),'authenticated cannot record outcome');
select ok(not has_function_privilege('anon','public.record_mobile_push_retry_outcome(uuid,uuid,jsonb)','execute'),'anonymous cannot record outcome');
set local role service_role;
select set_config('audit.push_claim', public.claim_mobile_push_retry('a9500000-0000-4000-8000-000000000004',1)::text,true);
select is((select attempt_count from public.mobile_push_deliveries where id='a9500000-0000-4000-8000-000000000004'),2,'attempt spent before provider request');
select is((select receipt_error_code from public.mobile_push_deliveries where id='a9500000-0000-4000-8000-000000000004'),'PushRetryOutcomeUnknown','unknown outcome explicit');
select is(public.claim_mobile_push_retry('a9500000-0000-4000-8000-000000000004',2),null::uuid,'active claim cannot be replaced');
select throws_ok($$select public.record_mobile_push_retry_outcome('a9500000-0000-4000-8000-000000000004',current_setting('audit.push_claim')::uuid,'{"status":"sent"}')$$,'22023',null,'accepted outcome requires ticket');
select is(public.finish_mobile_push_retry('a9500000-0000-4000-8000-000000000004',gen_random_uuid())->>'applied','false','foreign claim cannot retire');
select is((select is_active from public.mobile_push_tokens where id='a9500000-0000-4000-8000-000000000002'),true,'foreign claim leaves token active');
reset role;
update public.mobile_push_deliveries set retry_claim_until=now()-interval '1 second' where id='a9500000-0000-4000-8000-000000000004';
set local role service_role;
select set_config('audit.push_claim_new', public.claim_mobile_push_retry('a9500000-0000-4000-8000-000000000004',2)::text,true);
select is((select attempt_count from public.mobile_push_deliveries where id='a9500000-0000-4000-8000-000000000004'),3,'expired claim spends final budget slot');
select is(public.finish_mobile_push_retry('a9500000-0000-4000-8000-000000000004',current_setting('audit.push_claim')::uuid)->>'applied','false','old worker cannot overwrite replacement');
select ok(public.record_mobile_push_retry_outcome('a9500000-0000-4000-8000-000000000004',current_setting('audit.push_claim_new')::uuid,'{"status":"refused","error_code":"DeviceNotRegistered"}'),'refusal saved before cleanup');
select is(public.finish_mobile_push_retry('a9500000-0000-4000-8000-000000000004',current_setting('audit.push_claim_new')::uuid)->>'disabledTokenCount','1','final attempt retires token');
select is((select receipt_status from public.mobile_push_deliveries where id='a9500000-0000-4000-8000-000000000004'),'stale','refusal terminal');
select is((select is_active from public.mobile_push_tokens where id='a9500000-0000-4000-8000-000000000002'),false,'token retired in same transaction');
select is(public.finish_mobile_push_retry('a9500000-0000-4000-8000-000000000004',current_setting('audit.push_claim_new')::uuid)->>'applied','false','repeated finalization inert');
select throws_ok($$select public.claim_mobile_push_retry('a9500000-0000-4000-8000-000000000004',3)$$,'22023',null,'no fourth attempt');
reset role;
select * from finish();
rollback;
